use super::*;

/// Every KIND stem, for a refusal message. It cannot name the technologies — this process holds no
/// store — so the refusal names the kinds and the shape, and points at `bsc session list`, which is
/// answered by the app against the real axis.
pub fn valid_ids() -> Vec<&'static str> {
    STUDIO_KINDS.iter().map(|k| k.kind).collect()
}
